contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // Fund the contract enough to pay the 100 wei reward.
        require(address(this).balance >= 100, "need 100 wei");

        bool firstAttempt;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstAttempt = false;
        } else {
            firstAttempt = true;
        }

        bool secondAttempt;
        bool secondReverted;
        c.getFirstWithdrawalBonus(recipient); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondAttempt = true;
        }

        // Verify that a second call cannot succeed after any first call (success or revert).
        assert(!(firstAttempt || secondAttempt) || (!secondAttempt && secondReverted));
    }

    receive() external payable {}
}

